window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bac80aa520b817e5"]={"versions": [{"id": "FIG-bac80aa520b817e5", "releases": ["R1.3.0", "R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt das Serialisierungslayout (In-Memory- bzw. On-Wire-Payload-Struktur) eines zweidimensionalen statischen Arrays fester Länge (<code>Static Array a[n][m]</code>) im SOME/IP-Protokoll dar. Es dient der Spezifikation der Byte-Reihenfolge bei der Übertragung mehrdimensionaler Datentypen über die SOME/IP-Kommunikationsschicht im AUTOSAR-Gesamtkontext.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Static Array a[n][m]</code>: Übergeordneter Container für ein 2D-Array der Dimension $n \\times m$.</li>\n<li><code>Element_1</code>, <code>Element_2</code>, <code>...</code>, <code>Element_n</code>: Die $n$ Zeilen bzw. Teil-Arrays erster Ordnung des Arrays.</li>\n<li><code>E1,1</code>, <code>E1,2</code>, <code>...</code>, <code>E1,m</code>: Die $m$ einzelnen skalaren bzw. zusammengesetzten Nutzdatenelemente innerhalb des ersten Teil-Arrays <code>Element_1</code>.</li>\n<li><code>e</code>: Elementgröße eines einzelnen Nutzdatenelements in Bytes.</li>\n<li><code>m * e</code>: Gesamtlänge einer einzelnen Zeile (<code>Element_1</code>) in Bytes.</li>\n<li><code>n <em> ( m </em> e )</code>: Gesamte Serialisierungslänge des 2D-Arrays in Bytes.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Serialisierung erfolgt sequenziell in zeilenweiser Anordnung (Row-Major-Order) direkt hintereinander ohne zwischenliegende Längenindikatoren oder Padding:</p>\n<ol class=\"fig-list\">\n<li>Zunächst werden die Elemente der ersten Dimension serialisiert, beginnend mit <code>Element_1</code>.</li>\n<li>Innerhalb von <code>Element_1</code> werden sukzessive die Unterelemente <code>E1,1</code>, <code>E1,2</code> bis <code>E1,m</code> serialisiert.</li>\n<li>Im direkten Anschluss folgen <code>Element_2</code> bis <code>Element_n</code> nach demselben Schema, bis alle $n \\times m$ Elemente abgearbeitet sind.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß <code>[PRS_SOMEIP_00101]</code> folgt die Serialisierung mehrdimensionaler statischer Arrays exakt dem Speicherlayout mehrdimensionaler Arrays gängiger Programmiersprachen (Row-Major-Order). Es existieren in dieser Fassung keine Längenfelder im Byte-Strom. Implementierer müssen sicherstellen, dass Sender und Empfänger identische statische Konfigurationsparameter bezüglich der Dimensionen $n$, $m$ und der Elementgröße $e$ besitzen, da die Gesamtlänge strikt $n \\times m \\times e$ Bytes beträgt.</p>"}, {"id": "FIG-6e2852c33f21a23f", "releases": ["R1.5.1", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt das Serialisierungslayout (In-Memory- bzw. On-Wire-Payload-Struktur) eines zweidimensionalen statischen Arrays fester Länge (<code>Static Array a[n][m]</code>) im SOME/IP-Protokoll dar. Es dient der Spezifikation der Byte-Reihenfolge bei der Übertragung mehrdimensionaler Datentypen über die SOME/IP-Kommunikationsschicht im AUTOSAR-Gesamtkontext.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Static Array a[n][m]</code>: Übergeordneter Container für ein 2D-Array der Dimension $n \\times m$.</li>\n<li><code>Element_1</code>, <code>Element_2</code>, <code>...</code>, <code>Element_n</code>: Die $n$ Zeilen bzw. Teil-Arrays erster Ordnung des Arrays.</li>\n<li><code>E1,1</code>, <code>E1,2</code>, <code>...</code>, <code>E1,m</code>: Die $m$ einzelnen skalaren bzw. zusammengesetzten Nutzdatenelemente innerhalb des ersten Teil-Arrays <code>Element_1</code>.</li>\n<li><code>e</code>: Elementgröße eines einzelnen Nutzdatenelements in Bytes.</li>\n<li><code>m * e</code>: Gesamtlänge einer einzelnen Zeile (<code>Element_1</code>) in Bytes.</li>\n<li><code>n <em> ( m </em> e )</code>: Gesamte Serialisierungslänge des 2D-Arrays in Bytes.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Serialisierung erfolgt sequenziell in zeilenweiser Anordnung (Row-Major-Order) direkt hintereinander ohne zwischenliegende Längenindikatoren oder Padding:</p>\n<ol class=\"fig-list\">\n<li>Zunächst werden die Elemente der ersten Dimension serialisiert, beginnend mit <code>Element_1</code>.</li>\n<li>Innerhalb von <code>Element_1</code> werden sukzessive die Unterelemente <code>E1,1</code>, <code>E1,2</code> bis <code>E1,m</code> serialisiert.</li>\n<li>Im direkten Anschluss folgen <code>Element_2</code> bis <code>Element_n</code> nach demselben Schema, bis alle $n \\times m$ Elemente abgearbeitet sind.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß <code>[PRS_SOMEIP_00101]</code> folgt die Serialisierung mehrdimensionaler statischer Arrays exakt dem Speicherlayout mehrdimensionaler Arrays gängiger Programmiersprachen (Row-Major-Order). Es existieren in dieser Fassung keine Längenfelder im Byte-Strom. Implementierer müssen sicherstellen, dass Sender und Empfänger identische statische Konfigurationsparameter bezüglich der Dimensionen $n$, $m$ und der Elementgröße $e$ besitzen, da die Gesamtlänge strikt $n \\times m \\times e$ Bytes beträgt.</p>"}, {"id": "FIG-2c5da72b39aa7e0a", "releases": ["R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt das Serialisierungslayout (In-Memory- bzw. On-Wire-Payload-Struktur) eines zweidimensionalen statischen Arrays fester Länge (<code>Static Array a[n][m]</code>) im SOME/IP-Protokoll dar. Es dient der Spezifikation der Byte-Reihenfolge bei der Übertragung mehrdimensionaler Datentypen über die SOME/IP-Kommunikationsschicht im AUTOSAR-Gesamtkontext.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Static Array a[n][m]</code>: Übergeordneter Container für ein 2D-Array der Dimension $n \\times m$.</li>\n<li><code>Element_1</code>, <code>Element_2</code>, <code>...</code>, <code>Element_n</code>: Die $n$ Zeilen bzw. Teil-Arrays erster Ordnung des Arrays.</li>\n<li><code>E1,1</code>, <code>E1,2</code>, <code>...</code>, <code>E1,m</code>: Die $m$ einzelnen skalaren bzw. zusammengesetzten Nutzdatenelemente innerhalb des ersten Teil-Arrays <code>Element_1</code>.</li>\n<li><code>e</code>: Elementgröße eines einzelnen Nutzdatenelements in Bytes.</li>\n<li><code>m * e</code>: Gesamtlänge einer einzelnen Zeile (<code>Element_1</code>) in Bytes.</li>\n<li><code>n <em> ( m </em> e )</code>: Gesamte Serialisierungslänge des 2D-Arrays in Bytes.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Serialisierung erfolgt sequenziell in zeilenweiser Anordnung (Row-Major-Order) direkt hintereinander ohne zwischenliegende Längenindikatoren oder Padding:</p>\n<ol class=\"fig-list\">\n<li>Zunächst werden die Elemente der ersten Dimension serialisiert, beginnend mit <code>Element_1</code>.</li>\n<li>Innerhalb von <code>Element_1</code> werden sukzessive die Unterelemente <code>E1,1</code>, <code>E1,2</code> bis <code>E1,m</code> serialisiert.</li>\n<li>Im direkten Anschluss folgen <code>Element_2</code> bis <code>Element_n</code> nach demselben Schema, bis alle $n \\times m$ Elemente abgearbeitet sind.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß <code>[PRS_SOMEIP_00101]</code> folgt die Serialisierung mehrdimensionaler statischer Arrays exakt dem Speicherlayout mehrdimensionaler Arrays gängiger Programmiersprachen (Row-Major-Order). Es existieren in dieser Fassung keine Längenfelder im Byte-Strom. Implementierer müssen sicherstellen, dass Sender und Empfänger identische statische Konfigurationsparameter bezüglich der Dimensionen $n$, $m$ und der Elementgröße $e$ besitzen, da die Gesamtlänge strikt $n \\times m \\times e$ Bytes beträgt.</p>"}, {"id": "FIG-2916004a7605ca58", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert das Serialisierungs- und Drahtformat eines statischen mehrdimensionalen Arrays (<code>Static Array [n][m]</code>) im SOME/IP-Protokoll, einschließlich der Repräsentation optional konfigurierbarer Längenfelder (<code>LengthField (optional)</code>) auf den verschiedenen Hierarchieebenen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Static Array [n][m]</code>: Hauptcontainer des zweidimensionalen Arrays.</li>\n<li><code>LengthField (optional)</code>: Optionales Längenfeld auf Gesamtebene sowie auf Ebene der einzelnen Zeilenelemente (<code>Element_1</code>, <code>Element_2</code>).</li>\n<li><code>Element_1</code>, <code>Element_2</code>, <code>...</code>, <code>Element_n</code>: Die $n$ Zeilen-Arrays bzw. Unterstrukturen.</li>\n<li><code>E1,1</code>, <code>...</code>, <code>E1,m</code> bzw. <code>E2,1</code>, <code>...</code>, <code>E2,m</code>: Die $m$ Datenelemente der jeweiligen Zeile.</li>\n<li><code>e</code>: Größe eines einzelnen Datenelements.</li>\n<li><code>m*e</code>: Kumulierte Nutzdatenlänge der $m$ Elemente einer Zeile.</li>\n<li><code>n<em>(LengthField + m</em>e)</code>: Gesamtlänge aller $n$ Elemente inklusive deren zeilenindividueller optionaler Längenfelder.</li>\n<li><code>LengthField + n<em>(LengthField + m</em>e)</code>: Gesamtlänge des serialisierten Arrays einschließlich des übergeordneten optionalen Längenfelds.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Serialisierung verläuft hierarchisch nach Row-Major-Order unter Einbettung optionaler Längeninformationen:</p>\n<ol class=\"fig-list\">\n<li>Falls konfiguriert, wird vorab das übergeordnete <code>LengthField (optional)</code> des Gesamt-Arrays übertragen.</li>\n<li>Es folgt <code>Element_1</code>, welches bei entsprechender Konfiguration mit einem eigenen <code>LengthField (optional)</code> beginnt, gefolgt von seinen Elementen <code>E1,1</code> bis <code>E1,m</code>.</li>\n<li>Unmittelbar danach folgt <code>Element_2</code>, beginnend mit dessen optionalem Längenfeld und den Elementen <code>E2,1</code> bis <code>E2,m</code>.</li>\n<li>Der Ablauf setzt sich linear fort bis zum Abschluss von <code>Element_n</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation berücksichtigt die konfigurierbare Unterstützung von Längenfeldern für statische Arrays (<code>LengthField (optional)</code> mit typischerweise 0, 8, 16 oder 32 Bit). Wenn Längenfelder aktiviert sind, erweitert sich die PDU-Länge pro Hierarchieebene entsprechend der Formel <code>LengthField + n<em>(LengthField + m</em>e)</code>. Bei einer Längenfeldgröße von 0 Bit reduziert sich das Format auf das reine Nutzdaten-Speicherlayout. Parser und Serialisierer müssen die Längenfeldkonfiguration auf jeder Dimensionsebene exakt abbilden.</p>"}], "trans": [{"from": "FIG-bac80aa520b817e5", "to": "FIG-6e2852c33f21a23f", "fr": "R1.3.0", "tr": "R1.5.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6e2852c33f21a23f", "to": "FIG-bac80aa520b817e5", "fr": "R1.5.1", "tr": "R17-03_R1.1.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-bac80aa520b817e5", "to": "FIG-2c5da72b39aa7e0a", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2c5da72b39aa7e0a", "to": "FIG-6e2852c33f21a23f", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6e2852c33f21a23f", "to": "FIG-2c5da72b39aa7e0a", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2c5da72b39aa7e0a", "to": "FIG-2916004a7605ca58", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Äußere Datenstruktur</strong>: Überschrift von <code>Static Array a[n][m]</code> zu <code>Static Array [n][m]</code> geändert.</li>\n<li><strong>Längenfelder</strong>: Voranstellung eines optionalen Felds <code>LengthField (optional)</code> vor die Gesamtreihe der Elemente auf äußerer Array-Ebene sowie innerhalb jeder Dimension (<code>Element_1</code>, <code>Element_2</code>) vor die Unterelemente.</li>\n<li><strong>Unterelemente</strong>: Explizite Ausdetaillierung von <code>Element_2</code> mit <code>LengthField (optional)</code>, <code>E2,1</code>, <code>...</code>, <code>E2,m</code> analog zu <code>Element_1</code>.</li>\n<li><strong>Größenbemaßungen</strong>: Anpassung der Bemaßungen unter Berücksichtigung der Längenfelder von <code>m <em> e</code> auf <code>m</em>e</code> (nur für die Nutzdaten), <code>n<em>(LengthField + m</em>e)</code> für die Summe der Array-Elemente sowie <code>LengthField + n<em>(LengthField + m</em>e)</code> für das Gesamt-Array.</li>\n</ul>"}]};
